遍历字符串，判断字符是否为元音字母 a/e/i/o/u，计数累加。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char s[105];
    cin >> s;
    int cnt = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u')
            cnt++;
    }
    cout << cnt << endl;
    return 0;
}
```

读入字符与字符串，遍历字符串统计与 c 相等的字符个数。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char c, s[105];
    cin >> c >> s;
    int cnt = 0;
    for (int i = 0; s[i] != '\0'; i++)
        if (s[i] == c) cnt++;
    cout << cnt << endl;
    return 0;
}
```

遍历字符串，用小写字母区间和大写字母区间分别计数，输出时先小写后大写。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char s[105];
    cin >> s;
    int low = 0, up = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') low++;
        else if (s[i] >= 'A' && s[i] <= 'Z') up++;
    }
    cout << low << " " << up << endl;
    return 0;
}
```

先遍历求字符串长度 n，再从 n-1 到 0 倒序输出每个字符。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char s[105];
    cin >> s;
    int n = 0;
    while (s[n] != '\0') n++;
    for (int i = n - 1; i >= 0; i--)
        cout << s[i];
    cout << endl;
    return 0;
}
```

遍历字符串，用字符区间判断是否为数字字符并计数。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    char s[105];
    cin >> s;
    int cnt = 0;
    for (int i = 0; s[i] != '\0'; i++)
        if (s[i] >= '0' && s[i] <= '9') cnt++;
    cout << cnt << endl;
    return 0;
}
```
